  study: ["Study", "पढ़ाई", "পড়াশোনা", "అధ్యయనం", "अभ्यास", "படிப்பு", "અભ્યાસ", "ಅಧ್ಯಯನ", "പഠനം", "ਪੜ੍ਹਾਈ"],
  sessions: ["Sessions", "सत्र", "সেশন", "సెషన్లు", "सत्रे", "அமர்வுகள்", "સત્રો", "ಅಧಿವೇಶನಗಳು", "സെഷനുകൾ", "ਸੈਸ਼ਨ"],
